import{Z as e,e as n,f as i,a0 as o}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"iContact","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/email-marketing/icontact.md","filePath":"integrations/email-marketing/icontact.md","lastUpdated":1780377007000}'),a={name:"integrations/email-marketing/icontact.md"};function r(s,t,l,c,h,d){return n(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="icontact" tabindex="-1">iContact <a class="header-anchor" href="#icontact" aria-label="Permalink to &quot;iContact&quot;">​</a></h1><p>Connect iContact to send newsletter sign-ups to your chosen mailing list. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Email Marketing</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select iContact as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-icontact-api" tabindex="-1">Step 2. Connect to the iContact API <a class="header-anchor" href="#step-2-connect-to-the-icontact-api" aria-label="Permalink to &quot;Step 2. Connect to the iContact API&quot;">​</a></h3><ol><li>Go to <a href="https://www.icontact.com/" target="_blank">iContact</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Settings &amp; Billing</strong>.</li><li>Click on <strong>iContact Integrations</strong>.</li><li>Find the <strong>Custom API Integrations</strong> item and click the <strong>Create</strong> button.</li><li>Copy the <strong>Application ID (AppId)</strong> from iContact and paste in the <strong>Application ID</strong> field in Formie.</li><li>Copy the <strong>Username / Email Address</strong> from iContact and paste in the <strong>Username</strong> field in Formie.</li><li>Copy the <strong>Password</strong> from iContact and paste in the <strong>Password</strong> field in Formie.</li><li>Copy the <strong>Account ID</strong> from iContact and paste in the <strong>Account ID</strong> field in Formie.</li><li>Copy the <strong>Client Folder ID</strong> from iContact and paste in the <strong>Client Folder ID</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Select the destination list and map its required email field to your form’s Email Address field. Map any additional fields your list requires using the variable picker. If you collect a newsletter opt-in, configure integration conditions so only visitors who choose it are sent.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Look up the test email in the selected list and check its mapped values and subscription state. If the provider requires confirmation, complete that step before expecting an active subscription.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const m=e(a,[["render",r]]);export{p as __pageData,m as default};
